const wb = $('Webhook').first().json.body || {};
const customerId = wb.customer_id || 'غير محدد';
const patientName = wb.customer_name || 'Patient';
const orderCount = parseInt(wb.order_count) || 0;
const condition = wb.chronic_condition || 'Not specified';
const daysSinceJoin = parseInt(wb.days_since_join) || 0;

const orders = $('Get Patient Orders').all().filter(r => r.json && r.json.order_id);
const cycles = $('Get Churn Data').all().filter(r => r.json && r.json.drug_name);

const recentDrugs = orders.slice(0,3).map(o => o.json.drugs || 'unknown').join('; ');
const chronicDrugs = cycles.map(c => c.json.drug_name).filter(Boolean).join(', ') || 'None recorded';

let refillAlert = 'لا يوجد موعد إعادة صرف حرج حالياً';
if (cycles.length > 0) {
  const cycle = cycles[0].json;
  if (cycle.last_purchase_date && cycle.avg_cycle_days) {
    const lastDate = new Date(cycle.last_purchase_date);
    const avgDays = parseFloat(cycle.avg_cycle_days) || 30;
    const nextDate = new Date(lastDate.getTime() + avgDays * 24 * 60 * 60 * 1000);
    const daysLeft = Math.ceil((nextDate.getTime() - Date.now()) / (24 * 60 * 60 * 1000));
    if (daysLeft <= 14 && daysLeft >= 0) {
      refillAlert = `موعد إعادة صرف ${cycle.drug_name} خلال ${daysLeft} يوم`;
    } else if (daysLeft < 0) {
      refillAlert = `تنبيه: تأخر صرف ${cycle.drug_name} بـ ${Math.abs(daysLeft)} يوم`;
    }
  }
} else if (orderCount > 0) {
  refillAlert = 'ينصح بمتابعة صرف الجرعات بانتظام كل 30 يوماً.';
}

const prompt = `You are a professional pharmacy clinical AI.
Patient: ${patientName}
Condition: ${condition}
Total orders: ${orderCount}
Recent drugs: ${recentDrugs || 'None'}
Chronic drugs: ${chronicDrugs}

Provide a short clinical health evaluation in EXACTLY 3 lines:
INTERACTION_CHECK: [one concise Arabic sentence verifying medication safety and absence of conflicts]
REFILL_ALERT: [one concise Arabic sentence about refill timing]
AI_RECOMMENDATION: [one actionable Arabic clinical tip for this patient]`;

return [{json:{
  customer_id: customerId,
  patient_name: patientName,
  order_count: orderCount,
  chronic_condition: condition,
  recent_drugs: recentDrugs,
  chronic_drugs: chronicDrugs,
  refill_alert: refillAlert,
  orders_found: orders.length,
  cycles_found: cycles.length,
  ollama_prompt: prompt
}}];

const data = $('Build Health Prompt').first().json;
const raw = $('Ask Ollama').first().json.response || '';

const get = (key) => {
  const m = raw.match(new RegExp(key + ':\\s*(.+?)(?=\\n[A-Z_]+:|$)', 'si'));
  return m ? m[1].trim() : null;
};

const interactionCheck = get('INTERACTION_CHECK') || 'تم التحقق من الأدوية المسجلة ولا توجد تعارضات مسجلة.';
const refillAlertAI = get('REFILL_ALERT') || data.refill_alert;
const aiRec = get('AI_RECOMMENDATION') || 'احرص على أخذ الأدوية في مواعيدها المحددة ومراجعة الصيدلي دورياً.';

return [{json:{
  customer_id: data.customer_id,
  patient_name: data.patient_name,
  order_count: data.order_count,
  chronic_condition: data.chronic_condition,
  recent_drugs: data.recent_drugs,
  chronic_drugs: data.chronic_drugs,
  orders_found: data.orders_found,
  cycles_found: data.cycles_found,
  interaction_check: interactionCheck,
  refill_alert: refillAlertAI,
  ai_recommendation: aiRec,
  llm_source: 'ollama:AI-COS-LFM-Q4'
}}];
